use std::num::ParseIntError;

fn triple(s: &str) -> Result<u64, ParseIntError> {
    let n: u64 = s.parse()?;
    Ok(n * 3)
}

fn main() {
    match triple("21") {
        Ok(v) => println!("ok: {}", v),
        Err(e) => println!("error: {}", e),
    }
    match triple("nope") {
